    79    // We want to select n values at random (without repetition),
    80    // with 0 < n <= N.  The algorithm is taken from TAoCP, Vol. 2
    81    // (Algorithm S, selection sampling technique)
    82    struct Random
    83    {
    84      int  n;
    85      int  N;
    86
    87      int  t; // total number of values so far
    88      int  m; // number of selected values so far
    89
    90      uint32_t  r; // the current pseudo-random number
    91
    92      Random( int n_,
    93              int N_ )
    94      : n( n_ ),
    95        N( N_ )
    96      {
    97        t = 0;
    98        m = 0;
    99
   100        // Ideally, this should depend on the input file,
   101        // for example, taking the sha256 as input;
   102        // however, this is overkill for fuzzying tests.
   103        r = 12345;
   104      }
   105
   106      int get()
   107      {
   108        if ( m >= n )
   109          return -1;
   110
   111      Redo:
   112        // We can't use `rand': different C libraries might provide
   113        // different implementations of this function.  As a replacement,
   114        // we use a 32bit version of the `xorshift' algorithm.
   115        r ^= r << 13;
   116        r ^= r >> 17;
   117        r ^= r << 5;
   118
   119        double  U = double( r ) / UINT32_MAX;
   120
   121        if ( ( N - t ) * U >= ( n - m ) )
   122        {
   123          t++;
   124          goto Redo;
   125        }
   126
   127        t++;
   128        m++;
   129
   130        return t;
   131      }
   132    };
