   160    static vector<vector<FT_Byte>>
   161    parse_data( const uint8_t*  data,
   162                size_t          size )
   163    {
   164      struct archive_entry*    entry;
   165      int                      r;
   166      vector<vector<FT_Byte>>  files;
   167
   168      unique_ptr<struct  archive,
   169                 decltype ( archive_read_free )*>  a( archive_read_new(),
   170                                                      archive_read_free );
   171
   172      // activate reading of uncompressed tar archives
   173      archive_read_support_format_tar( a.get() );
   174
   175      // the need for `const_cast' was removed with libarchive commit be4d4dd
   176      if ( !( r = archive_read_open_memory(
   177                    a.get(),
   178                    const_cast<void*>(static_cast<const void*>( data ) ),
   179                    size ) ) )
   180      {
   181        unique_ptr<struct  archive,
   182                   decltype ( archive_read_close )*>  a_open( a.get(),
   183                                                              archive_read_close );
   184
   185        // read files contained in archive
   186        for (;;)
   187        {
   188          r = archive_read_next_header( a_open.get(), &entry );
   189          if ( r == ARCHIVE_EOF )
   190            break;
   191          if ( r != ARCHIVE_OK )
   192            break;
   193
   194          vector<FT_Byte>  entry_data;
   195          r = archive_read_entry_data( a.get(), &entry_data );
   196          if ( r != ARCHIVE_OK )
   197            break;
   198
   199          files.push_back( move( entry_data ) );
   200        }
   201      }
   202
   203      if ( files.size() == 0 )
   204        files.emplace_back( data, data + size );
   205
   206      return files;
   207    }
