   210    static void
   211    setIntermediateAxis( FT_Face  face )
   212    {
   213      // only handle Multiple Masters and GX variation fonts
   214      if ( !FT_HAS_MULTIPLE_MASTERS( face ) )
   215        return;
   216
   217      // get variation data for current instance
   218      FT_MM_Var*  variations_ptr = nullptr;
   219      if ( FT_Get_MM_Var( face, &variations_ptr ) )
   220        return;
   221
   222      unique_ptr<FT_MM_Var,
   223                 decltype ( free )*>  variations( variations_ptr, free );
   224      vector<FT_Fixed>                coords( variations->num_axis );
   225
   226      // select an arbitrary instance
   227      for ( unsigned int  i = 0; i < variations->num_axis; i++ )
   228        coords[i] = ( variations->axis[i].minimum +
   229                      variations->axis[i].def     ) / 2;
   230
   231      if ( FT_Set_Var_Design_Coordinates( face,
   232                                          FT_UInt( coords.size() ),
   233                                          coords.data() ) )
   234        return;
   235    }
