   238    // the interface function to the libFuzzer library
   239    extern "C" int
   240    LLVMFuzzerTestOneInput( const uint8_t*  data,
   241                            size_t          size_ )
   242    {
   243      assert( !InitResult );
   244
   245      if ( size_ < 1 )
   246        return 0;
   247
   248      const vector<vector<FT_Byte>>&  files = parse_data( data, size_ );
   249
   250      FT_Face         face;
   251      FT_Int32        load_flags  = FT_LOAD_DEFAULT;
   252  #if 0
   253      FT_Render_Mode  render_mode = FT_RENDER_MODE_NORMAL;
   254  #endif
   255
   256      // We use a conservative approach here, at the cost of calling
   257      // `FT_New_Face' quite often.  The idea is that the fuzzer should be
   258      // able to try all faces and named instances of a font, expecting that
   259      // some faces don't work for various reasons, e.g., a broken subfont, or
   260      // an unsupported NFNT bitmap font in a Mac dfont resource that holds
   260      // an unsupported NFNT bitmap font in a Mac dfont resource that holds
   261      // more than a single font.
   262
   263      // get number of faces
   264      if ( FT_New_Memory_Face( library,
   265                               files[0].data(),
   266                               (FT_Long)files[0].size(),
   267                               -1,
   268                               &face ) )
   269        return 0;
   270      long  num_faces = face->num_faces;
   271      FT_Done_Face( face );
   272
   273      // loop over all faces
   274      for ( long  face_index = 0;
   275            face_index < num_faces;
   276            face_index++ )
   277      {
   278        // get number of instances
   279        if ( FT_New_Memory_Face( library,
   280                                 files[0].data(),
   281                                 (FT_Long)files[0].size(),
   282                                 -( face_index + 1 ),
   283                                 &face ) )
   284          continue;
   285        long  num_instances = face->style_flags >> 16;
   286        FT_Done_Face( face );
   287
   288        // load face with and without instances
   289        for ( long  instance_index = 0;
   290              instance_index < num_instances + 1;
   291              instance_index++ )
   292        {
   293          if ( FT_New_Memory_Face( library,
   294                                   files[0].data(),
   295                                   (FT_Long)files[0].size(),
   296                                   ( instance_index << 16 ) + face_index,
   297                                   &face ) )
   298            continue;
   299
   300          // if we have more than a single input file coming from an archive,
   301          // attach them (starting with the second file) using the order given
   302          // in the archive
   303          for ( size_t  files_index = 1;
   304                files_index < files.size();
   305                files_index++ )
   306          {
   307            FT_Open_Args  open_args = {};
   308            open_args.flags         = FT_OPEN_MEMORY;
   309            open_args.memory_base   = files[files_index].data();
   310            open_args.memory_size   = (FT_Long)files[files_index].size();
   311
   312            // the last archive element will be eventually used as the
   313            // attachment
   314            FT_Attach_Stream( face, &open_args );
   315          }
   316
   317          // loop over an arbitrary size for outlines (index 0)
   318          // and up to ten arbitrarily selected bitmap stroke sizes (index 1-10)
   319          int  max_idx = face->num_fixed_sizes < 10
   320                           ? face->num_fixed_sizes
   321                           : 10;
   322
   323          Random pool( max_idx, face->num_fixed_sizes );
   324
   325          for ( int  idx = 0; idx <= max_idx; idx++ )
   326          {
   327            FT_Int32  flags = load_flags;
   328
   329            if ( !idx )
   330            {
   331              // set up 20pt at 72dpi as an arbitrary size
   332              if ( FT_Set_Char_Size( face, 20 * 64, 20 * 64, 72, 72 ) )
   333                continue;
   334              flags |= FT_LOAD_NO_BITMAP;
   335            }
   336            else
   337            {
   338              // bitmap strokes are not active for glyph variations
   339              if ( instance_index )
   340                continue;
   341
   342              if ( FT_Select_Size( face, pool.get() - 1 ) )
   343                continue;
   344              flags |= FT_LOAD_COLOR;
   345            }
   346
   347            // test MM interface only for a face without a selected instance
   348            if ( instance_index == 0 )
   349              setIntermediateAxis( face );
   350
   351            // loop over all glyphs
   352            for ( unsigned int  glyph_index = 0;
   353                  glyph_index < (unsigned int)face->num_glyphs;
   354                  glyph_index++ )
   355            {
   356              if ( FT_Load_Glyph( face, glyph_index, flags ) )
   357                continue;
   358
   359              // Rendering is the most expensive and the least interesting part.
   360              //
   361              // if ( FT_Render_Glyph( face->glyph, render_mode) )
   362              //   continue;
   363              // FT_GlyphSlot_Embolden( face->glyph );
   364
   365  #if 0
   366              FT_Glyph  glyph;
   367              if ( !FT_Get_Glyph( face->glyph, &glyph ) )
   368                FT_Done_Glyph( glyph );
   369
   370              FT_Outline*  outline = &face->glyph->outline;
   371              FT_Matrix    rot30   = { 0xDDB4, -0x8000, 0x8000, 0xDDB4 };
   372
   373              FT_Outline_Transform( outline, &rot30 );
   374
   375              FT_BBox  bbox;
   376              FT_Outline_Get_BBox( outline, &bbox );
   377  #endif
   378            }
   379          }
   380          FT_Done_Face( face );
   381        }
   382      }
   383
   384      return 0;
   385    }
